args.CommandLine:
"$paths = @(
    "C:\Users\lg\AppData\Local\Google\Chrome\User Data\Default\Cache",
    "C:\Users\lg\AppData\Local\Google\Chrome\User Data\Default\Code Cache",
    "C:\Users\lg\AppData\Local\Microsoft\Edge\User Data\Default\Cache",
    "C:\Users\lg\AppData\Local\Microsoft\Edge\User Data\Default\Code Cache",
    "C:\Users\lg\AppData\Roaming\Cursor\Cache",
    "C:\Users\lg\AppData\Roaming\Cursor\CachedData",
    "C:\Users\lg\AppData\Roaming\Code\Cache",
    "C:\Users\lg\AppData\Roaming\Code\CachedData"
)
foreach ($path in $paths) {
    if (Test-Path $path) {
        $size = (Get-ChildItem $path -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        [PSCustomObject]@{ Path = $path; SizeMB = [Math]::Round($size / 1MB, 2) }
    }
}"
